const queries = [
  "quasi-projective group scheme of finite type over a field",
  "projective morphism descends along faithfully flat base change",
  "immersion descends along faithfully flat base change",
  "quasi-projectivity descends along field extension",
  "ample invertible sheaf descends faithfully flat"
];
for (const q of queries) {
  const r = await tools.exec_command({
    cmd:`"$HORIZON_BIN" search ${JSON.stringify(q)} --json 2>/dev/null`,
    workdir:"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
    yield_time_ms:30000,
    max_output_tokens:14000
  });
  text(`--- ${q} ---\n${r.output}`);
}

