  tools.exec_command({cmd:"nl -ba AlgebraicJacobian/Picard/FiniteMapProjectiveImmersion.lean | sed -n '500,630p'; nl -ba AlgebraicJacobian/Picard/FiniteMorphismEmbedding.lean | sed -n '1,90p'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge","yield_time_ms":10000,"max_output_tokens":40000}),
