]);
for (let i=0;i<results.length;i++){ text(`RESULT ${i+1}\n${results[i].output}`); }

const cmds = [
  '"$HORIZON_BIN" task list --json | jq \'{warnings, tasks: (.tasks | map(select(.id == "rev2-ajc" or .id == "ajcr-fiberdeg-vanish" or .id == "ajc-proj-infra" or .id == "ajcr-review-family-producer" or .id == "ajcr-review-sepclosed-cover" or .id == "ajcr-review-rank-one-openness" or .id == "ajcr-fibre-presented-producer" or .id == "ajcr-native-base-change-iso") | {id,status,roadmap_refs}))}\'',
  'rg --files .archon-horizon/inbox/local | rg \'I-(1821|1952|1954|1955|1960|1964)\''
];
const rs = [];
for (const cmd of cmds) {
  rs.push(await tools.exec_command({
    cmd,
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
    yield_time_ms: 30000,
    max_output_tokens: 20000
  }));
}
text(`task-statuses\n${rs[0].output}`);
text(`comment-files\n${rs[1].output}`);

